WITH t AS (SELECT {{today}} AS d), p AS (SELECT p.object_id AS id, CAST(json_extract_string(p.state,'$.date') AS DATE) AS day, json_extract_string(a.state,'$.type') AS typ, CASE WHEN json_extract_string(p.state,'$.side') = 'debit' THEN CAST(json_extract(p.state,'$.amount') AS BIGINT) ELSE -CAST(json_extract(p.state,'$.amount') AS BIGINT) END AS b FROM objects p JOIN objects a ON json_extract_string(p.state,'$.account') = a.object_id WHERE p.object_type = 'posting' AND a.object_type = 'account' AND COALESCE(json_extract_string(p.state,'$.book'), 'main') = 'pl-stat' AND json_extract_string(a.state,'$.type') IN ('revenue', 'expense')), w(k, period, lo, hi) AS (SELECT 1, strftime(d, '%Y-%m') || ' do dziś, miesiąc trwa', CAST(date_trunc('month', d) AS DATE), d FROM t UNION ALL SELECT 2, strftime(CAST(date_trunc('month', d) - INTERVAL 1 MONTH AS DATE), '%Y-%m') || CASE WHEN EXISTS (SELECT 1 FROM objects WHERE object_type = 'period_lock' AND json_extract_string(state,'$.month') = strftime(CAST(date_trunc('month', d) - INTERVAL 1 MONTH AS DATE), '%Y-%m') AND COALESCE(json_extract_string(state,'$.book'), 'pl-stat') = 'pl-stat') THEN ', zamknięty' ELSE ', jeszcze niezamknięty' END, CAST(date_trunc('month', d) - INTERVAL 1 MONTH AS DATE), CAST(date_trunc('month', d) - INTERVAL 1 DAY AS DATE) FROM t UNION ALL SELECT 3, strftime(d, '%Y') || ' od stycznia', make_date(year(d), 1, 1), d FROM t) SELECT period, revenue, costs, result, o AS _of FROM (SELECT w.k, w.period, -COALESCE(SUM(p.b) FILTER (WHERE p.typ = 'revenue'), 0) AS revenue, COALESCE(SUM(p.b) FILTER (WHERE p.typ = 'expense'), 0) AS costs, -COALESCE(SUM(p.b), 0) AS result, COALESCE(string_agg(p.id, ',' ORDER BY p.id), '') AS o FROM w LEFT JOIN p ON p.day BETWEEN w.lo AND w.hi GROUP BY w.k, w.period) ORDER BY k
